static void mesh_gate_del ( struct mesh_table * tbl , struct mesh_path * mpath ) { if ( ! mpath -> is_gate ) { return ; } mpath -> is_gate = false ; spin_lock_bh ( & tbl -> gates_lock ) ; hlist_del_rcu ( & mpath -> gate_list ) ; mpath -> sdata -> u . mesh . num_gates -- ; spin_unlock_bh ( & tbl -> gates_lock ) ; mpath_dbg ( mpath -> sdata , "Mesh path: Deleted gate: %pM. %d known gates\n" , mpath -> dst , mpath -> sdata -> u . mesh . num_gates ) ; } 